content.css:
.ep-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #1C2928;
  -webkit-font-smoothing: antialiased;
  font-variant-numeric: tabular-nums;
}
.ep-root * {
  box-sizing: border-box;
}
.ep-empty {
  color: #87918E;
  font-size: 12px;
  padding: 12px;
}
.ep-src {
  color: #87918E;
  font-size: 10px;
  letter-spacing: 0.02em;
  margin-left: 6px;
}
.ep-cardtitle {
  font-size: 14px;
  font-weight: 700;
  color: #1C2928;
  letter-spacing: -0.005em;
}
.ep-car-note {
  font-size: 11px;
  color: #87918E;
  margin-top: 2px;
}
.ep-car-head {
  padding: 10px 14px 0;
}
.ep-svg {
  display: block;
  overflow: visible;
}
.ep-axis {
  font-size: 10.5px;
  fill: #87918E;
}
.ep-ev {
  font-size: 10.5px;
  font-weight: 600;
  fill: #8A6516;
}
.ep-endlab {
  font-size: 11.5px;
  font-weight: 700;
  fill: #1C2928;
}
.ep-ar {
  font-family: 'Segoe UI', Tahoma, sans-serif;
}
@keyframes ep-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
/* header */
.ep-header {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 100%;
  padding: 4px 6px;
}
.ep-mark {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  flex: none;
  display: grid;
  place-items: center;
  background: linear-gradient(140deg, #12958B, #0B6E69 60%, #07514D);
  box-shadow: 0 8px 18px -8px rgba(11, 110, 105, 0.7);
}
.ep-htitle {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.05;
  display: flex;
  align-items: baseline;
  gap: 12px;
  white-space: nowrap;
}
.ep-htitle-ar {
  font-size: 20px;
  font-weight: 700;
  color: #C2922F;
}
.ep-hsub {
  font-size: 12px;
  color: #4F5F5C;
  margin-top: 4px;
  white-space: nowrap;
}
/* KPI tiles */
.ep-kpis {
  display: flex;
  gap: 10px;
  height: 100%;
  padding: 2px;
}
.ep-kpi {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 12px 12px 10px;
  background: #fff;
  border: 1px solid #E8E1D4;
  border-radius: 14px;
  box-shadow: 0 6px 16px -12px rgba(60, 45, 20, 0.35);
  animation: ep-rise 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  position: relative;
  overflow: hidden;
}
.ep-kpi::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(#12958B, #C2922F);
  opacity: 0.9;
}
.ep-kpi-ic {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: #E3F1EF;
  display: grid;
  place-items: center;
  flex: none;
}
.ep-kpi-body {
  min-width: 0;
  flex: 1;
}
.ep-kpi-label {
  font-size: 11.5px;
  font-weight: 600;
  color: #4F5F5C;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ep-kpi-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-top: 1px;
}
.ep-kpi-ar {
  font-size: 11px;
  font-weight: 600;
  color: #C2922F;
  line-height: 1.25;
  text-align: right;
  min-width: 0;
  max-width: 52%;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.ep-kpi-val {
  font-size: 27px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: #1C2928;
  white-space: nowrap;
  flex: none;
}
.ep-kpi-sub {
  font-size: 10.5px;
  color: #87918E;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ep-kpi-sub .ep-src {
  margin-left: 4px;
  color: #B3AC9F;
}
/* insights */
.ep-ins {
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: 100%;
  padding: 10px 12px;
  overflow: hidden;
}
.ep-in {
  border-left: 3px solid #C2922F;
  padding: 4px 0 4px 10px;
  animation: ep-rise 0.6s ease both;
}
.ep-in-head {
  display: flex;
  align-items: center;
  gap: 6px;
}
.ep-in-title {
  font-size: 13px;
  font-weight: 700;
}
.ep-in-body {
  font-size: 12px;
  color: #4F5F5C;
  line-height: 1.4;
  margin-top: 2px;
}
.ep-in-ar {
  font-size: 12px;
  color: #1C2928;
  line-height: 1.5;
  margin-top: 4px;
  text-align: right;
}
.ep-in-ar b {
  color: #0B6E69;
}
.ep-in .ep-src {
  margin-left: 0;
  margin-top: 3px;
  display: block;
}
/* carousel */
.ep-car {
  position: relative;
  height: 100%;
}
.ep-car-stage {
  position: absolute;
  left: 0;
  top: 48px;
  perspective: 800px;
}
.ep-car-item {
  position: absolute;
  left: 50%;
  top: 46%;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: transform 0.9s cubic-bezier(0.3, 0.7, 0.2, 1), opacity 0.9s, filter 0.9s;
}
.ep-car-item svg {
  display: block;
  filter: drop-shadow(0 10px 12px rgba(40, 30, 10, 0.18));
}
.ep-car-lab {
  text-align: center;
  margin-top: 4px;
}
.ep-car-share {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.ep-car-name {
  font-size: 11px;
  color: #4F5F5C;
  font-weight: 600;
}
.ep-car-item.is-front .ep-car-share {
  font-size: 22px;
  color: #0B6E69;
}
.ep-car-panel {
  position: absolute;
  right: 12px;
  top: 50px;
  bottom: 12px;
  width: 35%;
  display: flex;
  align-items: center;
}
.ep-car-card {
  width: 100%;
  background: linear-gradient(180deg, #FFFDF8, #FBF6EC);
  border: 1px solid #E8E1D4;
  border-radius: 16px;
  padding: 14px 16px;
  animation: ep-rise 0.45s ease both;
}
.ep-car-ptop {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ep-sw {
  width: 12px;
  height: 12px;
  border-radius: 4px;
  flex: none;
}
.ep-car-pname {
  font-size: 18px;
  font-weight: 800;
}
.ep-car-par {
  font-size: 14px;
  color: #C2922F;
  margin-left: auto;
  font-weight: 700;
}
.ep-car-pco {
  font-size: 11.5px;
  color: #4F5F5C;
  margin: 4px 0 8px;
}
.ep-badge {
  display: inline-block;
  font-size: 10.5px;
  padding: 3px 8px;
  border-radius: 99px;
  background: #EFEAE0;
  color: #4F5F5C;
  font-weight: 600;
}
.ep-badge.is-eg {
  background: #F7EEDA;
  color: #8A6516;
}
.ep-car-big {
  font-size: 40px;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-top: 10px;
  line-height: 1;
}
.ep-car-cap {
  font-size: 11px;
  color: #87918E;
  margin-top: 4px;
}
.ep-bar {
  height: 8px;
  background: #EEE7DA;
  border-radius: 99px;
  margin-top: 10px;
  overflow: hidden;
}
.ep-bar-fill {
  height: 100%;
  width: 0;
  border-radius: 99px;
  transition: width 0.9s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.ep-car-delta {
  font-size: 12px;
  font-weight: 700;
  margin-top: 10px;
}
.ep-car-delta.up {
  color: #1E8757;
}
.ep-car-delta.down {
  color: #C0412C;
}
.ep-car-delta.flat {
  color: #4F5F5C;
}
/* trend, map, forecast */
.ep-trend,
.ep-map,
.ep-fc {
  position: relative;
  height: 100%;
}
.ep-gov {
  cursor: pointer;
  transition: opacity 0.25s;
}
.ep-gov:hover {
  filter: brightness(0.94);
}
.ep-maplab {
  font-size: 10px;
  font-weight: 600;
  fill: #1C2928;
  pointer-events: none;
  paint-order: stroke;
  stroke: rgba(255, 255, 255, 0.85);
  stroke-width: 3px;
}
.ep-maplab-v {
  font-weight: 800;
  font-size: 11px;
}
.ep-inset-t {
  font-size: 10px;
  font-weight: 700;
  fill: #4F5F5C;
}
.ep-legend {
  position: absolute;
  left: 14px;
  bottom: 8px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  font-size: 10.5px;
  color: #4F5F5C;
}
.ep-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.ep-chip i {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  display: inline-block;
  border: 1.5px solid transparent;
}
.ep-hollow {
  background: none !important;
  border: 1.3px solid rgba(28, 41, 40, 0.45) !important;
  border-radius: 50% !important;
}
.ep-dash {
  border-style: dashed !important;
  height: 0 !important;
  width: 14px !important;
  border-width: 1.5px 0 0 0 !important;
  border-radius: 0 !important;
}
.ep-ramp {
  width: 90px;
  height: 8px;
  border-radius: 99px;
  display: inline-block;
}
.ep-legend-note {
  color: #87918E;
}
.ep-fc-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.ep-toggle {
  display: flex;
  background: #F1EBE0;
  padding: 3px;
  border-radius: 10px;
  gap: 2px;
}
.ep-tg {
  border: 0;
  background: transparent;
  font: 700 11.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #4F5F5C;
  padding: 5px 12px;
  border-radius: 8px;
  cursor: pointer;
}
.ep-tg.on {
  background: #fff;
  color: #0B6E69;
  box-shadow: 0 2px 6px -2px rgba(0, 0, 0, 0.2);
}
/* tooltip */
.ep-tip {
  position: absolute;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.12s;
  z-index: 50;
  min-width: 150px;
  background: rgba(28, 41, 40, 0.96);
  color: #fff;
  border-radius: 10px;
  padding: 8px 10px;
  font-size: 11.5px;
  box-shadow: 0 10px 24px -10px rgba(0, 0, 0, 0.5);
}
.ep-tip-h {
  font-weight: 700;
  margin-bottom: 4px;
}
.ep-tip-sub {
  color: #B8C4C1;
  font-size: 10.5px;
  margin-bottom: 4px;
}
.ep-tip-ev {
  color: #F0C870;
  font-size: 10.5px;
  margin-bottom: 4px;
}
.ep-tip-r {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 1px 0;
}
.ep-tip-r i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.ep-tip-r b {
  margin-left: auto;
  padding-left: 12px;
}
/* Ask AI */
.ep-ai {
  display: flex;
  height: 100%;
  gap: 0;
}
.ep-ai-side {
  width: 300px;
  flex: none;
  padding: 16px;
  border-right: 1px solid #E8E1D4;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: linear-gradient(180deg, #FBF7F0, #F7F1E6);
}
.ep-ai-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}
.ep-ai-logo {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: linear-gradient(140deg, #C2922F, #C2552D);
  box-shadow: 0 8px 18px -8px rgba(194, 85, 45, 0.8);
}
.ep-ai-title {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.ep-ai-sub {
  font-size: 11px;
  color: #4F5F5C;
}
.ep-ai-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.ep-ai-stat {
  background: #fff;
  border: 1px solid #E8E1D4;
  border-radius: 10px;
  padding: 8px 10px;
}
.ep-ai-stat b {
  display: block;
  font-size: 18px;
  color: #0B6E69;
}
.ep-ai-stat span {
  font-size: 10.5px;
  color: #4F5F5C;
}
.ep-ai-h {
  font-size: 11px;
  font-weight: 700;
  color: #4F5F5C;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-top: 2px;
}
.ep-ai-sug {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ep-ai-chip {
  text-align: start;
  border: 1px solid #E8E1D4;
  background: #fff;
  border-radius: 10px;
  padding: 7px 10px;
  font: 600 11.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #1C2928;
  cursor: pointer;
}
.ep-ai-chip:hover {
  border-color: #12958B;
  color: #0B6E69;
}
.ep-ai-how {
  margin-top: auto;
  font-size: 10.5px;
  color: #4F5F5C;
  line-height: 1.45;
}
.ep-ai-how b {
  display: block;
  color: #1C2928;
  font-size: 11px;
  margin-bottom: 2px;
}
.ep-ai-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  background: #fff;
}
.ep-ai-log {
  flex: 1;
  overflow-y: auto;
  padding: 18px 22px 8px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  scroll-behavior: smooth;
}
.ep-ai-empty {
  margin: auto;
  text-align: center;
  color: #4F5F5C;
}
.ep-ai-empty-ic {
  width: 64px;
  height: 64px;
  border-radius: 20px;
  margin: 0 auto 10px;
  background: #E3F1EF;
  display: grid;
  place-items: center;
}
.ep-ai-empty-t {
  font-size: 16px;
  font-weight: 700;
  color: #1C2928;
}
.ep-ai-empty-ar {
  font-size: 15px;
  color: #C2922F;
  margin-top: 4px;
  font-weight: 600;
}
.ep-ai-q {
  align-self: flex-end;
  max-width: 75%;
  background: #0B6E69;
  color: #fff;
  padding: 9px 14px;
  border-radius: 16px 16px 4px 16px;
  font-size: 13px;
  font-weight: 600;
  animation: ep-rise 0.35s ease both;
}
.ep-ai-q.rtl {
  border-radius: 16px 16px 16px 4px;
  align-self: flex-start;
  font-size: 14px;
}
.ep-ai-a {
  align-self: flex-start;
  width: min(620px, 92%);
  background: #FCFAF6;
  border: 1px solid #E8E1D4;
  border-radius: 4px 16px 16px 16px;
  padding: 12px 14px;
  animation: ep-rise 0.4s ease both;
}
.ep-ai-a.rtl {
  align-self: flex-end;
  border-radius: 16px 4px 16px 16px;
}
.ep-ai-tool {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font: 600 10.5px Consolas, 'Cascadia Mono', monospace;
  color: #0B6E69;
  background: #E3F1EF;
  padding: 3px 8px;
  border-radius: 6px;
}
.ep-ai-route {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font: 700 10.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #0B6E69;
  background: #E3F1EF;
  padding: 3px 9px;
  border-radius: 99px;
}
.ep-ai-route.is-llm {
  color: #8A6418;
  background: #F6EBD3;
}
.ep-ai-route.is-refused {
  color: #A33A25;
  background: #F6DDD5;
}
.ep-ai-ms {
  font-weight: 600;
  opacity: 0.7;
}
.ep-ai-calls {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 7px;
}
.ep-ai-call {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
  font: 600 10.5px Consolas, 'Cascadia Mono', monospace;
  color: #4F5F5C;
  animation: ep-rise 0.3s ease both;
}
.ep-ai-call b {
  color: #0B6E69;
}
.ep-ai-call small {
  font: 600 10px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #87918E;
}
.ep-ai-dax-b {
  margin-left: auto;
  border: 1px solid #E8E1D4;
  background: #fff;
  border-radius: 6px;
  padding: 1px 7px;
  font: 700 9.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #0B6E69;
  cursor: pointer;
}
.ep-ai-dax-b:hover {
  border-color: #12958B;
}
.ep-ai-dax {
  display: none;
  margin: 2px 0 4px;
  padding: 8px 10px;
  background: #13312F;
  color: #E3F1EF;
  border-radius: 8px;
  font: 10px/1.45 Consolas, 'Cascadia Mono', monospace;
  white-space: pre-wrap;
  max-height: 180px;
  overflow: auto;
}
.ep-ai-dax.on {
  display: block;
}
.ep-ai-try {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.ep-ai-try:empty {
  display: none;
}
.ep-ai-try .ep-ai-chip {
  font-size: 11px;
  padding: 5px 9px;
}
.ep-ai-guard {
  color: #1E8757;
  font-weight: 700;
}
.ep-ai-guard.bad {
  color: #C0412C;
}
.ep-ai-trace {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: Consolas, 'Cascadia Mono', monospace;
}
.ep-ai-fb {
  border: 1px solid #E8E1D4;
  background: #fff;
  border-radius: 6px;
  width: 20px;
  height: 18px;
  font-size: 8px;
  color: #87918E;
  cursor: pointer;
  padding: 0;
}
.ep-ai-fb.on,
.ep-ai-fb:hover {
  color: #0B6E69;
  border-color: #12958B;
}
.ep-ai-dots {
  display: inline-flex;
  gap: 3px;
}
.ep-ai-dots i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #0B6E69;
  animation: ep-dot 1s infinite;
}
.ep-ai-dots i:nth-child(2) {
  animation-delay: 0.15s;
}
.ep-ai-dots i:nth-child(3) {
  animation-delay: 0.3s;
}
@keyframes ep-dot {
  0%,
  100% {
    opacity: 0.2;
  }
  50% {
    opacity: 1;
  }
}
.ep-ai-text {
  font-size: 13.5px;
  line-height: 1.55;
  margin-top: 8px;
  color: #1C2928;
  min-height: 20px;
}
.ep-ai-a.rtl .ep-ai-text {
  font-size: 14.5px;
  line-height: 1.7;
}
.ep-ai-ch {
  margin-top: 6px;
}
.ep-ai-chart {
  display: block;
  overflow: visible;
}
.ep-ai-bl {
  font-size: 11.5px;
  fill: #4F5F5C;
  font-weight: 600;
}
.ep-ai-bv {
  font-size: 11.5px;
  font-weight: 700;
  fill: #1C2928;
}
.ep-ai-foot {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 10px;
  font-size: 10px;
  color: #87918E;
  margin-top: 6px;
}
.ep-ai-tk {
  color: #0B6E69;
  font-weight: 700;
}
.ep-ai-bar {
  display: flex;
  gap: 8px;
  padding: 12px 18px 16px;
  border-top: 1px solid #E8E1D4;
}
.ep-ai-input {
  flex: 1;
  border: 1.5px solid #E8E1D4;
  border-radius: 12px;
  padding: 10px 14px;
  font: 500 13.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #1C2928;
  outline: none;
  background: #FCFAF6;
