}
.ep-ai-a.is-live {
  box-shadow: 0 0 0 0 rgba(18, 149, 139, 0), 0 14px 34px -14px rgba(18, 149, 139, 0.55);
}
@keyframes ep-glow {
  0% {
    background-position: 0% 50%;
  }
  100% {
    background-position: 200% 50%;
  }
}
/* numbered notes (native pages) */
.ep-notes {
  height: 100%;
  display: flex;
  flex-direction: column;
  font-family: 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #1C2928;
}
.ep-notes-list {
  list-style: none;
  margin: 0;
  padding: 2px 4px 0 0;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  scrollbar-width: thin;
  scrollbar-color: #DDD3C2 transparent;
}
.ep-notes.is-grid .ep-notes-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 16px;
  align-content: start;
}
.ep-note {
  position: relative;
  display: flex;
  gap: 10px;
  padding: 8px 10px 8px 8px;
  border-radius: 12px;
  background: #FBF8F2;
  border: 1px solid #F0E9DD;
  opacity: 0;
  transform: translateY(4px);
  animation: ep-note-in 0.45s ease forwards;
}
@keyframes ep-note-in {
  to {
    opacity: 1;
    transform: none;
  }
}
.ep-note-n {
  flex: none;
  width: 28px;
  height: 28px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font: 800 11.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  letter-spacing: 0.02em;
}
.ep-note-main {
  min-width: 0;
  flex: 1;
}
.ep-note-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
  justify-content: space-between;
}
.ep-note-t {
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.25;
  color: #1C2928;
}
.ep-note-tag {
  flex: none;
  font: 700 8.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 2px 6px;
  border-radius: 99px;
}
.ep-note-ar {
  font: 600 11px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #A07A2A;
  margin-top: 2px;
  text-align: right;
}
.ep-note-b {
  font-size: 11.5px;
  line-height: 1.42;
  color: #4F5F5C;
  margin-top: 3px;
}
.ep-note-src {
  font-size: 9.5px;
  color: #87918E;
  margin-top: 3px;
}
.ep-note.is-lead {
  background: linear-gradient(180deg, #F2F8F7, #FBF8F2);
  border-color: #D7EBE8;
}
.ep-note.is-lead .ep-note-n {
  background: linear-gradient(140deg, #12958B, #0B6E69);
  color: #fff;
  box-shadow: 0 6px 12px -8px rgba(11, 110, 105, 0.9);
}
.ep-note.is-lead .ep-note-tag {
  background: #E3F1EF;
  color: #0B6E69;
}
.ep-note.is-fact .ep-note-n {
  background: #fff;
  color: #0B6E69;
  border: 1.5px solid rgba(11, 110, 105, 0.55);
}
.ep-note.is-fact .ep-note-tag {
  background: #EEF5F3;
  color: #3F7D78;
}
.ep-note.is-watch .ep-note-n {
  background: linear-gradient(140deg, #D9AA4A, #C2922F);
  color: #fff;
  box-shadow: 0 6px 12px -8px rgba(194, 146, 47, 0.9);
}
.ep-note.is-watch .ep-note-tag {
  background: #F7EEDA;
  color: #8A6516;
}
.ep-note.is-method .ep-note-n {
  background: #fff;
  color: #4F5F5C;
  border: 1.5px dashed #BDB3A1;
}
.ep-note.is-method .ep-note-tag {
  background: #EFEAE0;
  color: #4F5F5C;
}
.ep-notes-empty {
  font-size: 12px;
  color: #87918E;
  padding: 12px;
}
.ep-notes-key {
  flex: none;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  padding: 8px 2px 0;
  margin-top: 6px;
  border-top: 1px solid #F0E9DD;
  font: 600 9.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #87918E;
}
.ep-notes-key span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.ep-notes-key i {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  display: inline-block;
}
.ep-notes-key .is-lead i {
  background: #0B6E69;
}
.ep-notes-key .is-fact i {
  background: #fff;
  border: 1.5px solid rgba(11, 110, 105, 0.55);
}
.ep-notes-key .is-watch i {
  background: #C2922F;
}
.ep-notes-key .is-method i {
  background: #fff;
  border: 1.5px dashed #BDB3A1;
}
/* Ask AI: chat history toolbar */
.ep-ai-main {
  position: relative;
}
.ep-ai-tb {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px 7px;
  border-bottom: 1px solid #E8E1D4;
  background: #FBF8F2;
}
.ep-ai-tbb {
  border: 1px solid #E8E1D4;
  background: #fff;
  border-radius: 99px;
  padding: 3px 10px;
  font: 700 11px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #4F5F5C;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
  flex: none;
}
.ep-ai-tbb:hover {
  border-color: #0B6E69;
  color: #0B6E69;
}
.ep-ai-tbn {
  background: #E3F1EF;
  color: #0B6E69;
  border-radius: 99px;
  padding: 0 6px;
  font-size: 10px;
  line-height: 15px;
}
.ep-ai-tbt {
  margin-left: auto;
  font-size: 10px;
  color: #87918E;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
.ep-ai-hist {
  position: absolute;
  left: 10px;
  right: 10px;
  top: 40px;
  max-height: 62%;
  overflow-y: auto;
  background: #fff;
  border: 1px solid #E8E1D4;
  border-radius: 12px;
  box-shadow: 0 18px 36px -18px rgba(0, 0, 0, 0.35);
  z-index: 5;
  display: none;
  padding: 6px;
}
.ep-ai-hist.on {
  display: block;
}
.ep-ai-hh {
  font: 700 9.5px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #B5862F;
  padding: 6px 10px 4px;
}
.ep-ai-hrow {
  display: block;
  width: 100%;
  text-align: start;
  border: 0;
  background: transparent;
  padding: 7px 10px;
  border-radius: 9px;
  cursor: pointer;
  font: 600 12px 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
  color: #1C2928;
}
.ep-ai-hrow b {
  display: block;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ep-ai-hrow small {
  display: block;
  color: #87918E;
  font-size: 10px;
  font-weight: 600;
  margin-top: 1px;
}
.ep-ai-hrow:hover {
  background: #F3EEE5;
}
.ep-ai-hrow.on {
  background: #E3F1EF;
}
/* landing page, read-only hosts, high contrast */
.ep-landing {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  text-align: center;
  font-family: 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, sans-serif;
}
.ep-landing b {
  font-size: 15px;
  color: #1C2928;
}
.ep-landing span {
  font-size: 12px;
  color: #87918E;
}
.ep-root.is-static button,
.ep-root.is-static .ep-ai-chip,
.ep-root.is-static .ep-ai-tbb {
  pointer-events: none;
  opacity: 0.6;
}
.ep-root.is-hc {
  background: var(--hc-bg) !important;
  color: var(--hc-fg) !important;
}
.ep-root.is-hc * {
  background-image: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
.ep-root.is-hc div,
.ep-root.is-hc span,
.ep-root.is-hc b,
.ep-root.is-hc small,
.ep-root.is-hc li,
.ep-root.is-hc button,
.ep-root.is-hc input,
.ep-root.is-hc td,
.ep-root.is-hc th {
  color: var(--hc-fg) !important;
  border-color: var(--hc-fg) !important;
}
.ep-root.is-hc .ep-note,
.ep-root.is-hc .ep-kpi,
.ep-root.is-hc .ep-ai-a,
.ep-root.is-hc .ep-ai-q,
.ep-root.is-hc .ep-ai-hist,
.ep-root.is-hc .ep-ai-bar,
.ep-root.is-hc .ep-ai-tb,
.ep-root.is-hc .ep-ai-side,
.ep-root.is-hc .ep-ai-main,
.ep-root.is-hc button,
.ep-root.is-hc input {
  background: var(--hc-bg) !important;
  border: 1px solid var(--hc-fg) !important;
}
.ep-root.is-hc .ep-note-n,
.ep-root.is-hc .ep-ai-send,
.ep-root.is-hc .on {
  background: var(--hc-sel) !important;
  color: var(--hc-bg) !important;
}
